<script setup>
import EditorialPhoto from '../Components/EditorialPhoto.vue';
import {ref,computed,onMounted,onUnmounted,watch,nextTick} from 'vue';import {saveReport,pending,receipts,syncReports,removeReceipt,removePending,smallPhoto,saveDraft,loadDraft,deleteDraft} from '../lib/offline';import {MapPin,Send,WifiOff,CheckCircle2} from 'lucide-vue-next';
const props=defineProps({localities:{type:Array,default:()=>[]},points:{type:Array,default:()=>[]}});const empty=()=>({locality_id:'',water_point_id:'',reporter_name:'',phone:'',relationship:'usager',problem:'pompe',description:'',landmark:'',observed_at:new Date().toLocaleDateString('en-CA'),latitude:null,longitude:null,gps_consent:null});const f=ref(empty()),error=ref(''),message=ref(''),busy=ref(false),photo=ref(null),queue=ref([]),received=ref([]),gps=ref(false),draft=ref(null);const points=computed(()=>props.points.filter(p=>p.locality_id==f.value.locality_id));watch(()=>f.value.locality_id,()=>f.value.water_point_id='');
async function refresh(){queue.value=await pending();received.value=await receipts();draft.value=await loadDraft();}onMounted(()=>{localStorage.setItem('eaurelais:catalogs',JSON.stringify({localities:props.localities,points:props.points}));refresh();addEventListener('eaurelais:queue',refresh)});onUnmounted(()=>removeEventListener('eaurelais:queue',refresh));
async function selectPhoto(e){error.value='';busy.value=true;try{photo.value=await smallPhoto(e.target.files[0]);}catch(x){error.value=x.message;photo.value=null;}finally{busy.value=false;}}
async function locate(){if(!gps.value){error.value='Autorisez d’abord la localisation.';return;}navigator.geolocation?.getCurrentPosition(p=>{f.value.latitude=p.coords.latitude;f.value.longitude=p.coords.longitude;f.value.gps_consent=1;},()=>error.value='Localisation indisponible. Vous pouvez utiliser un repère écrit.');}
async function keepDraft(){try{await saveDraft({form:{...f.value},photo:photo.value,gps:gps.value});await refresh();message.value='Brouillon enregistré uniquement sur cet appareil.';}catch(e){error.value='Impossible de sauvegarder le brouillon.';}} async function restoreDraft(){const data=draft.value;f.value={...data.form};photo.value=data.photo;gps.value=data.gps;await nextTick();f.value.water_point_id=data.form.water_point_id;} async function clearDraft(){await deleteDraft();draft.value=null;}
async function submit(){busy.value=true;error.value='';message.value='';try{const data={...f.value,water_point_id:f.value.water_point_id||null,client_uuid:crypto.randomUUID(),tracking_secret:Array.from(crypto.getRandomValues(new Uint8Array(32)),b=>b.toString(16).padStart(2,'0')).join(''),savedAt:Date.now()};if(!gps.value){data.latitude=null;data.longitude=null;data.gps_consent=null;}if(photo.value)data.photo=photo.value;await saveReport(data);await clearDraft();message.value='Enregistré sur cet appareil. En attente de confirmation du serveur.';f.value=empty();photo.value=null;await refresh();if(navigator.onLine){await syncReports();await refresh();}}catch(e){error.value=e.message||'Enregistrement local impossible. Vérifiez l’espace disponible.';}finally{busy.value=false;}}
async function discard(id){if(confirm('Supprimer ce signalement non envoyé de cet appareil ?')){await removePending(id);refresh();}}
function download(r){const blob=new Blob([`EauRelais\nRéférence : ${r.reference}\nCode secret : ${r.secret}\nSuivi : ${location.origin}/suivre\nConservez ce code à l’abri des regards.`],{type:'text/plain'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=r.reference+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
</script>
<template><section class="report-container"><div class="page-heading"><span class="eyebrow">UN GESTE UTILE POUR TOUTE LA COMMUNAUTÉ</span><h1>Signaler une panne</h1><p>Quelques informations pour aider la bonne équipe à intervenir.</p></div><div v-if="error" class="notice error" role="alert">{{error}}</div><div v-if="message" class="notice" role="status">{{message}}</div>
<div v-for="r in received" :key="r.reference" class="notice success receipt"><CheckCircle2/><div><strong>Signalement reçu par le serveur · {{r.reference}}</strong><p>Votre code secret : <code>{{r.secret}}</code></p><p>Conservez-le pour consulter le suivi et confirmer le retour de l’eau. Il expire sur cet appareil après 7 jours.</p><button class="btn btn-outline small" @click="download(r)">Télécharger mon reçu</button> <a href="/suivre" class="btn btn-soft small">Suivre</a> <button class="text-button" @click="removeReceipt(r.reference).then(refresh)">Effacer le reçu de cet appareil</button></div></div>
<div v-if="draft" class="notice"><strong>Un brouillon est enregistré sur cet appareil.</strong><div class="button-row mt"><button class="btn btn-soft small" @click="restoreDraft">Reprendre le brouillon</button><button class="text-button" @click="clearDraft">Effacer le brouillon</button></div></div><div v-if="queue.length" class="card queue"><h3><WifiOff :size="19"/> {{queue.length}} signalement(s) en attente</h3><div v-for="q in queue" :key="q.client_uuid" class="queue-item"><span>{{q.description}}<small class="error-text">{{q.error||'En attente d’envoi au serveur.'}}</small></span><button @click="discard(q.client_uuid)" class="text-button">Supprimer</button></div><button class="btn btn-outline small" @click="syncReports().then(refresh)">Réessayer l’envoi</button></div>
<div class="grid report-grid"><form class="card form-stack" @submit.prevent="submit"><h3><span class="form-number">1</span> Où se trouve le point d’eau ?</h3><label>Village ou quartier *<select v-model="f.locality_id" required><option value="" disabled>Choisir une localité</option><option v-for="l in localities" :value="l.id" :key="l.id">{{l.name}} · {{l.commune?.name}}</option></select></label><label>Point d’eau<select v-model="f.water_point_id"><option value="">Je ne trouve pas ce point d’eau</option><option v-for="p in points" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>Repère pour le retrouver<input v-model="f.landmark" maxlength="500" placeholder="Ex. : à côté de l’école, près du grand arbre"></label><label class="checkbox"><input type="checkbox" v-model="gps">J’accepte de partager la position de ce point d’eau.</label><button type="button" class="btn btn-soft small" @click="locate"><MapPin :size="16"/> Utiliser ma position</button><small v-if="f.latitude">Position ajoutée : {{Number(f.latitude).toFixed(4)}}, {{Number(f.longitude).toFixed(4)}}</small>
<h3><span class="form-number">2</span> Que se passe-t-il ?</h3><div class="grid two"><label>Type de problème *<select v-model="f.problem"><option value="pompe">Pompe bloquée</option><option value="absence">Absence d’eau</option><option value="debit">Débit faible</option><option value="fuite">Fuite visible</option><option value="equipement">Équipement endommagé</option><option value="aspect">Aspect, odeur ou goût inhabituel</option><option value="autre">Autre problème</option></select></label><label>Date du constat *<input type="date" v-model="f.observed_at" required :max="new Date().toLocaleDateString('en-CA')"></label></div><label>Description *<textarea v-model="f.description" required minlength="10" maxlength="3000" rows="4" placeholder="Décrivez ce que vous avez constaté..."></textarea></label><label>Photo facultative · JPEG, PNG ou WebP<input type="file" accept="image/jpeg,image/png,image/webp" @change="selectPhoto"><small>{{photo?'Photo compressée : '+Math.round(photo.size/1024)+' Ko':'La photo sera réduite avant l’envoi.'}}</small></label><p v-if="f.problem==='aspect'" class="notice">Cette observation doit être vérifiée. L’application ne peut pas établir la qualité sanitaire de l’eau.</p>
<h3><span class="form-number">3</span> Comment vous recontacter ?</h3><div class="grid two"><label>Votre nom ou prénom *<input v-model="f.reporter_name" required maxlength="100" autocomplete="name"></label><label>Téléphone *<input v-model="f.phone" type="tel" required minlength="8" maxlength="24" autocomplete="tel" placeholder="+229 01 XX XX XX XX"></label></div><label>Vous signalez en tant que<select v-model="f.relationship"><option value="usager">Usager</option><option value="ecole">Responsable d’école</option><option value="relais">Relais communautaire</option><option value="autre">Autre</option></select></label><p class="muted">Votre téléphone permet à l’équipe autorisée de préciser la panne et de vérifier le retour de l’eau. Il n’est pas affiché publiquement.</p><button type="button" class="btn btn-outline" :disabled="busy" @click="keepDraft">Enregistrer un brouillon sur cet appareil</button><button class="btn btn-primary" :disabled="busy||!localities.length"><Send :size="18"/>{{busy?'Enregistrement…':'Enregistrer et envoyer le signalement'}}</button></form>
<aside class="report-help"><div class="report-photo-card"><EditorialPhoto alt="Scène illustrative d’un point d’eau communautaire au Bénin." sizes="(max-width: 700px) 100vw, 350px"/><div><span class="eyebrow">VOTRE SIGNALEMENT EST UN PREMIER PAS</span><h3>Pour que l’eau retrouve<br>sa place dans le quotidien.</h3></div></div><div class="card tinted"><span class="eyebrow">ET ENSUITE ?</span><h3>Votre signalement suit son chemin.</h3><ol><li>L’équipe vérifie votre demande.</li><li>Un technicien peut être affecté.</li><li>Vous confirmez le retour de l’eau.</li></ol><p>Une référence et un code secret vous seront remis après réception.</p></div><div class="card"><WifiOff class="accent"/><h3>Le réseau vous lâche ?</h3><p>Votre demande reste sur cet appareil jusqu’à l’envoi. Revenez dans l’application lorsque la connexion est rétablie.</p><p class="muted">Sur un téléphone partagé, supprimez les demandes en attente et les reçus dont vous n’avez plus besoin.</p></div></aside></div></section></template>
